{"command":"cd /workspace; cat > src/decimal.rs <<'EOF'
//! A small fixed-point decimal number type used for parameter scans.
//!
//! Values are stored as a 96-bit (max) unsigned mantissa, a sign flag and a
//! decimal scale in the range `0..=28`.

use std::cmp::Ordering;
use std::fmt;

pub const MAX_SCALE: u32 = 28;
const MAX_MANTISSA: u128 = (1u128 << 96) - 1;

#[derive(Debug, Clone, Copy)]
pub struct Decimal {
    negative: bool,
    mantissa: u128,
    scale: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecimalParseError(pub String);

impl fmt::Display for DecimalParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Invalid decimal: {}", self.0)
    }
}

impl std::error::Error for DecimalParseError {}

fn pow10(n: u32) -> u128 {
    10u128.pow(n)
}

impl Decimal {
    pub const ZERO: Decimal = Decimal {
        negative: false,
        mantissa: 0,
        scale: 0,
    };
    pub const ONE: Decimal = Decimal {
        negative: false,
        mantissa: 1,
        scale: 0,
    };

    fn new(negative: bool, mantissa: u128, scale: u32) -> Decimal {
        Decimal {
            negative: negative && mantissa != 0,
            mantissa,
            scale,
        }
    }

    pub fn is_zero(&self) -> bool {
        self.mantissa == 0
    }

    pub fn parse(input: &str) -> Result<Decimal, DecimalParseError> {
        let bytes = input.as_bytes();
        if bytes.is_empty() {
            return Err(DecimalParseError("empty".into()));
        }
        let mut idx = 0;
        let mut negative = false;
        match bytes[0] {
            b'-' => {
                negative = true;
                idx = 1;
            }
            b'+' => {
                idx = 1;
            }
            _ => {}
        }
        if idx < bytes.len() && bytes[idx] == b'_' {
            return Err(DecimalParseError("must start lead with a number".into()));
        }

        let mut mantissa: u128 = 0;
        let mut scale: u32 = 0;
        let mut seen_point = false;
        let mut digits = 0usize;
        let mut rounding_digit: Option<u8> = None;
        let mut overflow_pending = false;

        while idx < bytes.len() {
            let b = bytes[idx];
            match b {
                b'0'..=b'9' => {
                    let d = (b - b'0') as u128;
                    digits += 1;
                    if seen_point && scale >= MAX_SCALE {
                        // Beyond maximum precision: only the first excess digit
                        // participates in rounding.
                        if rounding_digit.is_none() {
                            rounding_digit = Some(d as u8);
                        }
                    } else {
                        let next = mantissa.checked_mul(10).and_then(|m| m.checked_add(d));
                        match next {
                            Some(m) if m <= MAX_MANTISSA => {
                                mantissa = m;
                                if seen_point {
                                    scale += 1;
                                }
                            }
                            _ => {
                                if seen_point {
                                    // Can not represent more fractional digits:
                                    // use this digit for rounding.
                                    if rounding_digit.is_none() {
                                        rounding_digit = Some(d as u8);
                                    }
                                } else {
                                    overflow_pending = true;
                                }
                            }
                        }
                    }
                }
                b'.' => {
                    if seen_point {
                        return Err(DecimalParseError("two decimal points".into()));
                    }
                    seen_point = true;
                }
                b'_' => {}
                _ => {
                    return Err(DecimalParseError("unknown character".into()));
                }
            }
            idx += 1;
        }

        if overflow_pending {
            return Err(DecimalParseError("overflow from too many digits".into()));
        }
        if digits == 0 {
            return Err(DecimalParseError("no digits found".into()));
        }

        if let Some(rd) = rounding_digit {
            if rd >= 5 {
                mantissa += 1;
                if mantissa > MAX_MANTISSA {
                    return Err(DecimalParseError("overflow from too many digits".into()));
                }
            }
        }

        Ok(Decimal::new(negative, mantissa, scale))
    }

    pub fn scale(&self) -> u32 {
        self.scale
    }

    /// Signed mantissa together with the scale.
    fn signed(&self) -> i128 {
        if self.negative {
            -(self.mantissa as i128)
        } else {
            self.mantissa as i128
        }
    }

    /// Rescale a mantissa to a lower scale, rounding half away from zero.
    fn reduce_scale(mantissa: u128, from: u32, to: u32) -> u128 {
        if from <= to {
            return mantissa;
        }
        let div = pow10(from - to);
        let q = mantissa / div;
        let r = mantissa % div;
        if r * 2 >= div {
            q + 1
        } else {
            q
        }
    }

    /// Bring both operands to a common scale, returning signed mantissas.
    fn align(a: &Decimal, b: &Decimal) -> (i128, i128, u32) {
        let mut a_m = a.mantissa;
        let mut b_m = b.mantissa;
        let mut a_s = a.scale;
        let mut b_s = b.scale;

        while a_s < b_s {
            match a_m.checked_mul(10) {
                Some(m) if m <= MAX_MANTISSA => {
                    a_m = m;
                    a_s += 1;
                }
                _ => {
                    // Can not scale `a` up any further: reduce `b` instead.
                    b_m = Decimal::reduce_scale(b_m, b_s, a_s);
                    b_s = a_s;
                }
            }
        }
        while b_s < a_s {
            match b_m.checked_mul(10) {
                Some(m) if m <= MAX_MANTISSA => {
                    b_m = m;
                    b_s += 1;
                }
                _ => {
                    a_m = Decimal::reduce_scale(a_m, a_s, b_s);
                    a_s = b_s;
                }
            }
        }
        let a_v = if a.negative { -(a_m as i128) } else { a_m as i128 };
        let b_v = if b.negative { -(b_m as i128) } else { b_m as i128 };
        (a_v, b_v, a_s)
    }

    fn from_signed(value: i128, scale: u32) -> Option<Decimal> {
        let negative = value < 0;
        let mantissa = value.unsigned_abs();
        if mantissa > MAX_MANTISSA {
            // Try to reduce the scale to make the value fit.
            let mut m = mantissa;
            let mut s = scale;
            while m > MAX_MANTISSA && s > 0 {
                m = Decimal::reduce_scale(m, s, s - 1);
                s -= 1;
            }
            if m > MAX_MANTISSA {
                return None;
            }
            return Some(Decimal::new(negative, m, s));
        }
        Some(Decimal::new(negative, mantissa, scale))
    }

    pub fn checked_add(&self, other: &Decimal) -> Option<Decimal> {
        let (a, b, scale) = Decimal::align(self, other);
        Decimal::from_signed(a + b, scale)
    }

    pub fn checked_sub(&self, other: &Decimal) -> Option<Decimal> {
        let (a, b, scale) = Decimal::align(self, other);
        Decimal::from_signed(a - b, scale)
    }

    /// Integer part of `self / other` (truncated towards zero), for
    /// non-negative operands. Returns `None` on overflow of the result.
    pub fn div_trunc(&self, other: &Decimal) -> Option<u128> {
        if other.is_zero() {
            return None;
        }
        if self.is_zero() {
            return Some(0);
        }
        // self / other = (a_m / 10^a_s) / (b_m / 10^b_s)
        //              = a_m * 10^b_s / (b_m * 10^a_s)
        let (a_m, a_s, b_m, b_s) = (self.mantissa, self.scale, other.mantissa, other.scale);
        let quotient = if b_s >= a_s {
            let d = b_s - a_s;
            match a_m.checked_mul(pow10(d)) {
                Some(num) => num / b_m,
                None => {
                    // The numerator exceeds u128: the quotient is far beyond
                    // the representable range.
                    return None;
                }
            }
        } else {
            let d = a_s - b_s;
            match b_m.checked_mul(pow10(d)) {
                Some(den) => a_m / den,
                None => 0,
            }
        };
        if quotient > MAX_MANTISSA {
            None
        } else {
            Some(quotient)
        }
    }

    pub fn to_usize(&self) -> Option<usize> {
        if self.negative && self.mantissa != 0 {
            return None;
        }
        let int = self.mantissa / pow10(self.scale);
        usize::try_from(int).ok()
    }
}

impl PartialEq for Decimal {
    fn eq(&self, other: &Decimal) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}

impl Eq for Decimal {}

impl PartialOrd for Decimal {
    fn partial_cmp(&self, other: &Decimal) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Decimal {
    fn cmp(&self, other: &Decimal) -> Ordering {
        if self.is_zero() && other.is_zero() {
            return Ordering::Equal;
        }
        match (self.negative, other.negative) {
            (false, true) => return Ordering::Greater,
            (true, false) => return Ordering::Less,
            _ => {}
        }
        // Compare magnitudes without losing precision.
        let (a, b) = if self.scale >= other.scale {
            let d = self.scale - other.scale;
            match other.mantissa.checked_mul(pow10(d)) {
                Some(bm) => (self.mantissa, bm),
                None => (0, 1),
            }
        } else {
            let d = other.scale - self.scale;
            match self.mantissa.checked_mul(pow10(d)) {
                Some(am) => (am, other.mantissa),
                None => (1, 0),
            }
        };
        let ord = a.cmp(&b);
        if self.negative {
            ord.reverse()
        } else {
            ord
        }
    }
}

impl fmt::Display for Decimal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let digits = self.mantissa.to_string();
        let mut s = String::new();
        if self.negative {
            s.push('-');
        }
        if self.scale == 0 {
            s.push_str(&digits);
        } else {
            let scale = self.scale as usize;
            if digits.len() <= scale {
                s.push_str("0.");
                for _ in 0..(scale - digits.len()) {
                    s.push('0');
                }
                s.push_str(&digits);
            } else {
                let (int_part, frac_part) = digits.split_at(digits.len() - scale);
                s.push_str(int_part);
                s.push('.');
                s.push_str(frac_part);
            }
        }
        f.pad(&s)
    }
}

impl std::ops::Add for Decimal {
    type Output = Decimal;
    fn add(self, other: Decimal) -> Decimal {
        self.checked_add(&other).expect("Addition overflowed")
    }
}

impl std::ops::Sub for Decimal {
    type Output = Decimal;
    fn sub(self, other: Decimal) -> Decimal {
        self.checked_sub(&other).expect("Subtraction overflowed")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn p(s: &str) -> Decimal {
        Decimal::parse(s).unwrap()
    }

    #[test]
    fn parse_and_display() {
        assert_eq!(p("1.50").to_string(), "1.50");
        assert_eq!(p(".5").to_string(), "0.5");
        assert_eq!(p("1.").to_string(), "1");
        assert_eq!(p("+1").to_string(), "1");
        assert_eq!(p("-1.25").to_string(), "-1.25");
        assert_eq!(p("1_0").to_string(), "10");
        assert_eq!(p("1._5").to_string(), "1.5");
        assert_eq!(
            p("0.12345678901234567890123456789").to_string(),
            "0.1234567890123456789012345679"
        );
        assert_eq!(
            p("1.00000000000000000000000000005").to_string(),
            "1.0000000000000000000000000001"
        );
        assert_eq!(
            p("1.000000000000000000000000000001").to_string(),
            "1.0000000000000000000000000000"
        );
        assert_eq!(p("79228162514264337593543950335").to_string(), "79228162514264337593543950335");
    }

    #[test]
    fn parse_errors() {
        assert_eq!(Decimal::parse("").unwrap_err().0, "empty");
        assert_eq!(Decimal::parse("1.2.3").unwrap_err().0, "two decimal points");
        assert_eq!(Decimal::parse("_1").unwrap_err().0, "must start lead with a number");
        assert_eq!(Decimal::parse("-").unwrap_err().0, "no digits found");
        assert_eq!(Decimal::parse(".").unwrap_err().0, "no digits found");
        assert_eq!(Decimal::parse("1e5").unwrap_err().0, "unknown character");
        assert_eq!(Decimal::parse(" 1").unwrap_err().0, "unknown character");
        assert_eq!(
            Decimal::parse("79228162514264337593543950336").unwrap_err().0,
            "overflow from too many digits"
        );
    }

    #[test]
