        assert_eq!((p("1.50") + p("0.5")).to_string(), "2.00");
        assert_eq!((p("0.1") + p("0.2")).to_string(), "0.3");
        assert_eq!((p("-1.5") + p("0.25")).to_string(), "-1.25");
        assert_eq!((p("-1.25") + p("0.25")).to_string(), "-1.00");
        assert_eq!((p("3") - p("1")).to_string(), "2");
        assert_eq!((p("1") + p("1.000000000000000000000000000001")).to_string(), "2.0000000000000000000000000000");
        assert!(p("0.5") < p("1"));
        assert!(p("-1") < p("0.5"));
        assert!(p("1.0") == p("1"));
        assert_eq!(p("2.00001").div_trunc(&p("0.00002")), Some(100000));
        assert_eq!(p("1.99998").div_trunc(&p("0.00002")), Some(99999));
