//! POSIX-shell-like splitting and joining of command lines.

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError;

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("missing closing quote")
    }
}

impl std::error::Error for ParseError {}

enum State {
    /// Between words.
    Delimiter,
    /// Backslash seen while between words.
    Backslash,
    /// Inside an unquoted word.
    Unquoted,
    /// Backslash inside an unquoted word.
    UnquotedBackslash,
    /// Inside single quotes.
    SingleQuoted,
    /// Inside double quotes.
    DoubleQuoted,
    /// Backslash inside double quotes.
    DoubleQuotedBackslash,
    /// Inside a comment (until end of line).
    Comment,
}

/// Split a command line into words following POSIX shell quoting rules.
pub fn split(input: &str) -> Result<Vec<String>, ParseError> {
    use State::*;

    let mut words = Vec::new();
    let mut word = String::new();
    let mut state = Delimiter;

    for c in input.chars() {
        state = match state {
            Delimiter => match c {
                '\'' => SingleQuoted,
                '"' => DoubleQuoted,
                '\\' => Backslash,
                '\t' | ' ' | '\n' => Delimiter,
                '#' => Comment,
                _ => {
                    word.push(c);
                    Unquoted
                }
            },
            Backslash => match c {
                '\n' => Delimiter,
                _ => {
                    word.push(c);
                    Unquoted
                }
            },
            Unquoted => match c {
                '\'' => SingleQuoted,
                '"' => DoubleQuoted,
                '\\' => UnquotedBackslash,
                '\t' | ' ' | '\n' => {
                    words.push(std::mem::take(&mut word));
                    Delimiter
                }
                _ => {
                    word.push(c);
                    Unquoted
                }
            },
            UnquotedBackslash => match c {
                '\n' => Unquoted,
                _ => {
                    word.push(c);
                    Unquoted
                }
            },
            SingleQuoted => match c {
                '\'' => Unquoted,
                _ => {
                    word.push(c);
                    SingleQuoted
                }
            },
            DoubleQuoted => match c {
                '"' => Unquoted,
                '\\' => DoubleQuotedBackslash,
                _ => {
                    word.push(c);
                    DoubleQuoted
                }
            },
            DoubleQuotedBackslash => match c {
                '\n' => DoubleQuoted,
                '$' | '`' | '"' | '\\' => {
                    word.push(c);
                    DoubleQuoted
                }
                _ => {
                    word.push('\\');
                    word.push(c);
                    DoubleQuoted
                }
            },
            Comment => match c {
                '\n' => Delimiter,
                _ => Comment,
            },
        };
    }

    match state {
        SingleQuoted | DoubleQuoted | DoubleQuotedBackslash => return Err(ParseError),
        Delimiter | Comment => {}
        Backslash | UnquotedBackslash => {
            word.push('\\');
            words.push(word);
        }
        Unquoted => words.push(word),
    }

    Ok(words)
}

fn needs_quoting(s: &str) -> bool {
    s.is_empty()
        || s.chars().any(|c| {
            matches!(
                c,
                '|' | '&'
                    | ';'
                    | '<'
                    | '>'
                    | '('
                    | ')'
                    | '$'
                    | '`'
                    | '\\'
                    | '"'
                    | '\''
                    | ' '
                    | '\t'
                    | '\n'
                    | '*'
                    | '?'
                    | '['
                    | '#'
                    | '%'
                    | '='
            )
        })
}

/// Quote a single word so that it survives shell parsing.
pub fn quote(s: &str) -> String {
    if s.is_empty() {
        return "''".to_string();
    }
    if !needs_quoting(s) {
        return s.to_string();
    }
    let mut out = String::with_capacity(s.len() + 2);
    out.push('\'');
    for c in s.chars() {
        if c == '\'' {
            out.push_str("'\\''");
        } else {
            out.push(c);
        }
    }
    out.push('\'');
    out
}

/// Join words into a single command line, quoting where necessary.
pub fn join<I, S>(words: I) -> String
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    words
        .into_iter()
        .map(|w| quote(w.as_ref()))
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn splitting() {
        assert_eq!(
            split("echo 'a b' c \"d  e\" f\\ g").unwrap(),
            vec!["echo", "a b", "c", "d  e", "f g"]
        );
        assert_eq!(split("echo a #b c").unwrap(), vec!["echo", "a"]);
        assert_eq!(split("echo a#b c").unwrap(), vec!["echo", "a#b", "c"]);
        assert_eq!(split("echo a\\").unwrap(), vec!["echo", "a\\"]);
        assert_eq!(split("echo \"a\\$b\\`c\\\"d\\\\e\\nf\"").unwrap(), vec!["echo", "a$b`c\"d\\e\\nf"]);
        assert_eq!(split("i\\\nj").unwrap(), vec!["ij"]);
        assert!(split("echo 'a b").is_err());
        assert!(split("echo \"a").is_err());
        assert_eq!(split("   ").unwrap(), Vec::<String>::new());
    }

    #[test]
    fn joining() {
        assert_eq!(join(["sh", "-c", "exit 1"]), "sh -c 'exit 1'");
        assert_eq!(join(["x", "it's"]), "x 'it'\\''s'");
        assert_eq!(join(["x", "", "a=b", "~c", "%d", "e~", "f*"]), "x '' 'a=b' ~c '%d' e~ 'f*'");
        assert_eq!(join(["a]b", "a[b", "a{b", "a!b"]), "a]b 'a[b' a{b a!b");
    }
}
