//! Spawning of processes and measurement of their resource usage.

use std::fs::File;
use std::io;
use std::process::{Command, ExitStatus, Stdio};
use std::time::Instant;

use crate::units::Second;

/// Result of a single process execution.
#[derive(Debug, Clone, Copy)]
pub struct ExecuteResult {
    pub time_real: Second,
    pub time_user: Second,
    pub time_system: Second,
    pub memory_usage_byte: u64,
    pub status: ExitStatus,
}

/// Where the stdout of a benchmarked command goes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OutputPolicy {
    Null,
    Pipe,
    Inherit,
    File(std::path::PathBuf),
}

impl OutputPolicy {
    pub fn parse(value: &str) -> OutputPolicy {
        match value {
            "null" => OutputPolicy::Null,
            "pipe" => OutputPolicy::Pipe,
            "inherit" => OutputPolicy::Inherit,
            path => OutputPolicy::File(std::path::PathBuf::from(path)),
        }
    }

    fn stdio(&self) -> io::Result<(Stdio, Stdio)> {
        Ok(match self {
            OutputPolicy::Null => (Stdio::null(), Stdio::null()),
            OutputPolicy::Pipe => (Stdio::piped(), Stdio::null()),
            OutputPolicy::Inherit => (Stdio::inherit(), Stdio::inherit()),
            OutputPolicy::File(path) => {
                let file = File::create(path)?;
                (Stdio::from(file), Stdio::null())
            }
        })
    }
}

/// Where the stdin of a benchmarked command comes from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InputPolicy {
    Null,
    File(std::path::PathBuf),
}

impl InputPolicy {
    fn stdio(&self) -> io::Result<Stdio> {
        Ok(match self {
            InputPolicy::Null => Stdio::null(),
            InputPolicy::File(path) => Stdio::from(File::open(path)?),
        })
    }
}

fn timeval_to_seconds(tv: libc::timeval) -> Second {
    tv.tv_sec as f64 + tv.tv_usec as f64 * 1e-6
}

/// Wait for the child with the given pid and collect its resource usage.
fn wait4(pid: libc::pid_t) -> io::Result<(ExitStatus, libc::rusage)> {
    use std::os::unix::process::ExitStatusExt;
    let mut status: libc::c_int = 0;
    let mut rusage: libc::rusage = unsafe { std::mem::zeroed() };
    loop {
        let ret = unsafe { libc::wait4(pid, &mut status, 0, &mut rusage) };
        if ret == -1 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        break;
    }
    Ok((ExitStatus::from_raw(status), rusage))
}

/// Configure the standard streams of `command` and run it, measuring wall
/// clock time as well as CPU time and peak memory usage.
pub fn execute_and_measure(
    mut command: Command,
    input: &InputPolicy,
    output: &OutputPolicy,
) -> io::Result<ExecuteResult> {
    let stdin = input.stdio()?;
    let (stdout, stderr) = output.stdio()?;
    command.stdin(stdin).stdout(stdout).stderr(stderr);

    let start = Instant::now();
    let mut child = command.spawn()?;

    // Drain piped output so that the child never blocks on a full pipe.
    let drain = child.stdout.take().map(|mut stdout| {
        std::thread::spawn(move || {
            let _ = io::copy(&mut stdout, &mut io::sink());
        })
    });

    let (status, rusage) = wait4(child.id() as libc::pid_t)?;
    let time_real = start.elapsed().as_secs_f64();

    if let Some(handle) = drain {
        let _ = handle.join();
    }

    Ok(ExecuteResult {
        time_real,
        time_user: timeval_to_seconds(rusage.ru_utime),
        time_system: timeval_to_seconds(rusage.ru_stime),
        memory_usage_byte: (rusage.ru_maxrss as u64) * 1024,
        status,
    })
}

/// Map an exit status to an exit code, using `128 + signal` for processes
/// that were terminated by a signal.
pub fn exit_code(status: &ExitStatus) -> Option<i32> {
    use std::os::unix::process::ExitStatusExt;
    status.code().or_else(|| status.signal().map(|s| 128 + s))
}
