//! A terminal progress bar with a spinner, drawn to stderr.
//!
//! Layout: ` {spinner} {message:<30} {bar} ETA {hh:mm:ss} ` padded to the
//! full width of the terminal. The spinner advances on a steady tick (every
//! 80 ms); changes to the message or the length trigger an immediate redraw,
//! while increments of the position are picked up by the next tick.

use std::io::{self, IsTerminal, Write};
use std::sync::{Arc, Condvar, Mutex};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

const TICK_CHARS: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
const TICK_INTERVAL: Duration = Duration::from_millis(80);
const MESSAGE_WIDTH: usize = 30;
const FULL_CHAR: &str = "█";
const EMPTY_CHAR: &str = "░";

/// Leaky-bucket rate limiter for redraws (20 Hz, bursts of up to 20).
struct RateLimiter {
    interval_ms: u16,
    capacity: u8,
    prev: Instant,
}

const MAX_BURST: u8 = 20;

impl RateLimiter {
    fn new(rate_hz: u8) -> Self {
        Self {
            interval_ms: 1000 / rate_hz as u16,
            capacity: MAX_BURST,
            prev: Instant::now(),
        }
    }

    fn allow(&mut self, now: Instant) -> bool {
        if now < self.prev {
            return false;
        }
        let elapsed = now - self.prev;
        let interval = Duration::from_millis(self.interval_ms as u64);
        if self.capacity == 0 && elapsed < interval {
            return false;
        }
        let new = elapsed.as_millis() / self.interval_ms as u128;
        let remainder = elapsed.as_nanos() % (self.interval_ms as u128 * 1_000_000);
        self.capacity = (MAX_BURST as u128).min(self.capacity as u128 + new).saturating_sub(1) as u8;
        self.prev = now - Duration::from_nanos(remainder as u64);
        true
    }
}

/// Exponentially smoothed estimate of the progress rate.
struct Estimator {
    smoothed_steps_per_sec: f64,
    double_smoothed_steps_per_sec: f64,
    prev_steps: u64,
    prev_time: Instant,
    start_time: Instant,
}

fn estimator_weight(delta_t: f64) -> f64 {
    const EXPONENTIAL_WEIGHTING_SECONDS: f64 = 15.0;
    0.1_f64.powf(delta_t / EXPONENTIAL_WEIGHTING_SECONDS)
}

impl Estimator {
    fn new(now: Instant) -> Self {
        Self {
            smoothed_steps_per_sec: 0.0,
            double_smoothed_steps_per_sec: 0.0,
            prev_steps: 0,
            prev_time: now,
            start_time: now,
        }
    }

    fn record(&mut self, new_steps: u64, now: Instant) {
        if new_steps <= self.prev_steps || now <= self.prev_time {
            if new_steps < self.prev_steps {
                self.prev_steps = new_steps;
                self.smoothed_steps_per_sec = 0.0;
                self.double_smoothed_steps_per_sec = 0.0;
                self.prev_time = now;
                self.start_time = now;
            }
            return;
        }
        let delta_steps = new_steps - self.prev_steps;
        let delta_t = (now - self.prev_time).as_secs_f64();
        let new_steps_per_second = delta_steps as f64 / delta_t;
        let weight = estimator_weight(delta_t);
        self.smoothed_steps_per_sec =
            self.smoothed_steps_per_sec * weight + new_steps_per_second * (1.0 - weight);
        self.double_smoothed_steps_per_sec =
            self.double_smoothed_steps_per_sec * weight + self.smoothed_steps_per_sec * (1.0 - weight);
        self.prev_steps = new_steps;
        self.prev_time = now;
    }

    fn steps_per_second(&self, now: Instant) -> f64 {
        if self.prev_steps == 0 {
            return 0.0;
        }
        let elapsed = (now - self.start_time).as_secs_f64();
        if elapsed <= 0.0 {
            return 0.0;
        }
        let average = self.prev_steps as f64 / (self.prev_time - self.start_time).as_secs_f64().max(1e-9);
        let mut smoothed = 2.0 * self.smoothed_steps_per_sec - self.double_smoothed_steps_per_sec;
        if !(smoothed > 0.0) {
            smoothed = self.smoothed_steps_per_sec;
        }
        let weight = estimator_weight(elapsed);
        average * weight + smoothed * (1.0 - weight)
    }
}

struct State {
    pos: u64,
    len: u64,
    tick: u64,
    message: String,
    finished: bool,
    drawn_once: bool,
    rate_limiter: RateLimiter,
    estimator: Estimator,
}

/// Visible width of a string, ignoring ANSI escape sequences.
fn visible_width(s: &str) -> usize {
    let mut width = 0;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            if chars.peek() == Some(&'[') {
                chars.next();
                for d in chars.by_ref() {
                    if ('@'..='~').contains(&d) {
                        break;
                    }
                }
            }
            continue;
        }
        width += 1;
    }
    width
}

fn terminal_width() -> usize {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDERR_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            return ws.ws_col as usize;
        }
    }
    80
}

fn format_eta(seconds: f64) -> String {
    let mut t = if seconds.is_finite() && seconds > 0.0 {
        seconds.trunc() as u64
    } else {
        0
    };
    let secs = t % 60;
    t /= 60;
    let minutes = t % 60;
    t /= 60;
    let hours = t % 24;
    t /= 24;
    if t > 0 {
        format!("{}d {:02}:{:02}:{:02}", t, hours, minutes, secs)
    } else {
        format!("{:02}:{:02}:{:02}", hours, minutes, secs)
    }
}

impl State {
    fn fraction(&self) -> f32 {
        let pct = match (self.pos, self.len) {
            (_, 0) => 1.0,
            (0, _) => 0.0,
            (pos, len) => pos as f32 / len as f32,
        };
        pct.clamp(0.0, 1.0)
    }

    fn eta_seconds(&self, now: Instant) -> f64 {
        if self.finished || self.len == 0 {
            return 0.0;
        }
        let sps = self.estimator.steps_per_second(now);
        if sps == 0.0 {
            return 0.0;
        }
        self.len.saturating_sub(self.pos) as f64 / sps
    }

    fn render(&self, now: Instant, width: usize) -> String {
        let spinner = TICK_CHARS[(self.tick as usize) % TICK_CHARS.len()];
        let mut msg = self.message.clone();
        let msg_width = visible_width(&msg);
        for _ in msg_width..MESSAGE_WIDTH {
            msg.push(' ');
        }
        let eta = format_eta(self.eta_seconds(now));
        let prefix = format!(" {} {} ", spinner, msg);
        let suffix = format!(" ETA {} ", eta);
        let fixed = visible_width(&prefix) + visible_width(&suffix);
        let bar_width = width.saturating_sub(fixed);
        let filled = (self.fraction() * bar_width as f32) as usize;
        let filled = filled.min(bar_width);
        let mut bar = String::with_capacity(bar_width * 3);
        for _ in 0..filled {
            bar.push_str(FULL_CHAR);
        }
        for _ in filled..bar_width {
            bar.push_str(EMPTY_CHAR);
        }
        format!("{}{}{}", prefix, bar, suffix)
    }

    fn draw(&mut self, now: Instant, force: bool) {
        if !force && !self.rate_limiter.allow(now) {
            return;
        }
        let width = terminal_width();
        let line = self.render(now, width);
        let line_width = visible_width(&line);
        let mut out = String::new();
        if self.drawn_once {
            out.push_str("\r\x1b[2K");
        }
        out.push_str(&line);
        for _ in line_width..width {
            out.push(' ');
        }
        let stderr = io::stderr();
        let mut handle = stderr.lock();
        let _ = handle.write_all(out.as_bytes());
        let _ = handle.flush();
        self.drawn_once = true;
    }

    fn clear(&mut self) {
        if self.drawn_once {
            let stderr = io::stderr();
            let mut handle = stderr.lock();
            let _ = handle.write_all(b"\r\x1b[2K");
            let _ = handle.flush();
        }
        self.drawn_once = false;
    }
}

struct Ticker {
    stop: Arc<(Mutex<bool>, Condvar)>,
    handle: Option<JoinHandle<()>>,
}

pub struct ProgressBar {
    state: Option<Arc<Mutex<State>>>,
    ticker: Option<Ticker>,
}

impl ProgressBar {
    /// Create a hidden progress bar that never draws anything.
    pub fn hidden() -> ProgressBar {
        ProgressBar {
            state: None,
            ticker: None,
        }
    }

    /// Create a progress bar with the given length and message. Nothing is
    /// drawn unless stderr is a terminal.
    pub fn new(len: u64, message: &str) -> ProgressBar {
        if !io::stderr().is_terminal() {
            return ProgressBar::hidden();
        }
        let now = Instant::now();
        let state = Arc::new(Mutex::new(State {
            pos: 0,
            len,
            tick: 0,
            message: String::new(),
            finished: false,
            drawn_once: false,
            rate_limiter: RateLimiter::new(20),
            estimator: Estimator::new(now),
        }));

        let stop = Arc::new((Mutex::new(false), Condvar::new()));
        let ticker_state = Arc::clone(&state);
        let ticker_stop = Arc::clone(&stop);
        let handle = std::thread::spawn(move || loop {
            {
                let mut st = ticker_state.lock().unwrap();
                if st.finished {
                    break;
                }
                st.tick = st.tick.saturating_add(1);
                let now = Instant::now();
                let pos = st.pos;
                st.estimator.record(pos, now);
                st.draw(now, false);
            }
            let (lock, cvar) = &*ticker_stop;
            let guard = lock.lock().unwrap();
            let (guard, _) = cvar
                .wait_timeout_while(guard, TICK_INTERVAL, |stopped| !*stopped)
                .unwrap();
            if *guard {
                break;
            }
        });

        let bar = ProgressBar {
            state: Some(state),
            ticker: Some(Ticker {
                stop,
                handle: Some(handle),
            }),
        };
        bar.set_message(message.to_string());
        bar
    }

    pub fn set_message(&self, message: String) {
        if let Some(state) = &self.state {
            let mut st = state.lock().unwrap();
            st.message = message;
            let now = Instant::now();
            let pos = st.pos;
            st.estimator.record(pos, now);
            st.draw(now, false);
        }
    }

    pub fn set_length(&self, len: u64) {
        if let Some(state) = &self.state {
            let mut st = state.lock().unwrap();
            st.len = len;
            let now = Instant::now();
            let pos = st.pos;
            st.estimator.record(pos, now);
            st.draw(now, false);
        }
    }

    pub fn inc(&self, delta: u64) {
        if let Some(state) = &self.state {
            let mut st = state.lock().unwrap();
            st.pos = st.pos.saturating_add(delta);
        }
    }

    /// Stop the spinner and remove the bar from the terminal.
    pub fn finish_and_clear(&mut self) {
        if let Some(state) = &self.state {
            {
                let mut st = state.lock().unwrap();
                st.finished = true;
                st.clear();
            }
            if let Some(ticker) = self.ticker.take() {
                {
                    let (lock, cvar) = &*ticker.stop;
                    *lock.lock().unwrap() = true;
                    cvar.notify_all();
                }
                if let Some(handle) = ticker.handle {
                    let _ = handle.join();
