    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParameterScanError::ParseInt(e) => write!(f, "Error while parsing parameter scan arguments ({})", e),
            ParameterScanError::ParseDecimal(e) => write!(f, "Error while parsing parameter scan arguments ({})", e),
            ParameterScanError::EmptyRange => write!(f, "Empty parameter range"),
            ParameterScanError::TooLarge => write!(f, "Parameter range is too large"),
            ParameterScanError::ZeroStep => write!(f, "Zero is not a valid parameter step"),
            ParameterScanError::StepRequired => write!(
                f,
                "A step size is required when the range bounds are floating point numbers. \
                 The step size can be specified with the '-D/--parameter-step-size <DELTA>' parameter"
            ),
            ParameterScanError::UnboundedRange => write!(f, "Unbounded parameter range"),
        }
    }
}

impl std::error::Error for ParameterScanError {}

/// Numeric type that can be used for parameter scans.
pub trait Numeric: Copy + PartialOrd {
    fn zero() -> Self;
    fn one() -> Self;
    /// Wrapping addition (integers) or panicking addition (decimals).
    fn add(self, other: Self) -> Self;
    fn sub(self, other: Self) -> Self;
    /// Truncated division converted to usize, or `None` if that is impossible.
    fn div_to_usize(self, other: Self) -> Option<usize>;
    fn to_value(self) -> ParameterValue;
}

impl Numeric for i32 {
    fn zero() -> Self {
        0
    }
    fn one() -> Self {
        1
    }
    fn add(self, other: Self) -> Self {
        self.wrapping_add(other)
    }
    fn sub(self, other: Self) -> Self {
        self.wrapping_sub(other)
    }
    fn div_to_usize(self, other: Self) -> Option<usize> {
        let q = self.wrapping_div(other);
        usize::try_from(q).ok()
    }
    fn to_value(self) -> ParameterValue {
        ParameterValue::Integer(self)
    }
}

impl Numeric for Decimal {
    fn zero() -> Self {
        Decimal::ZERO
    }
    fn one() -> Self {
        Decimal::ONE
    }
    fn add(self, other: Self) -> Self {
        self + other
    }
    fn sub(self, other: Self) -> Self {
        self - other
    }
    fn div_to_usize(self, other: Self) -> Option<usize> {
        let q = self.div_trunc(&other).expect("Division overflowed");
        usize::try_from(q).ok()
    }
    fn to_value(self) -> ParameterValue {
        ParameterValue::Decimal(self)
    }
}

/// Inclusive range of values with a fixed step size.
pub struct RangeStep<T: Numeric> {
    state: T,
    end: T,
    step: T,
}

impl<T: Numeric> RangeStep<T> {
    pub fn new(start: T, end: T, step: T) -> Result<Self, ParameterScanError> {
        if end < start {
            return Err(ParameterScanError::EmptyRange);
        }
        if step == T::zero() {
            return Err(ParameterScanError::ZeroStep);
        }
        let count = end.sub(start).add(T::one()).div_to_usize(step);
        match count {
            Some(c) if c <= MAX_PARAMETERS => {}
            _ => return Err(ParameterScanError::TooLarge),
        }
        Ok(RangeStep {
            state: start,
            end,
            step,
        })
    }
}

impl<T: Numeric> Iterator for RangeStep<T> {
    type Item = T;

    fn next(&mut self) -> Option<T> {
        if self.state > self.end {
            return None;
        }
        let current = self.state;
        self.state = self.state.add(self.step);
        Some(current)
    }
}

/// Parse the `-P` arguments and produce the list of values.
pub fn parameter_scan_values(
    min: &str,
    max: &str,
    step: Option<&str>,
) -> Result<Vec<ParameterValue>, ParameterScanError> {
    let step_str = step.unwrap_or("1");
    if let (Ok(min_i), Ok(max_i), Ok(step_i)) =
        (min.parse::<i32>(), max.parse::<i32>(), step_str.parse::<i32>())
    {
        let range = RangeStep::new(min_i, max_i, step_i)?;
        return Ok(range.map(Numeric::to_value).collect());
    }

    let min_d = Decimal::parse(min).map_err(ParameterScanError::ParseDecimal)?;
    let max_d = Decimal::parse(max).map_err(ParameterScanError::ParseDecimal)?;
    let step_d = match step {
        Some(s) => Decimal::parse(s).map_err(ParameterScanError::ParseDecimal)?,
        None => return Err(ParameterScanError::StepRequired),
    };
    let range = RangeStep::new(min_d, max_d, step_d)?;
    Ok(range.map(Numeric::to_value).collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn values(min: &str, max: &str, step: Option<&str>) -> Vec<String> {
        parameter_scan_values(min, max, step)
            .unwrap()
            .iter()
            .map(|v| v.to_string())
            .collect()
    }

    #[test]
    fn integer_scan() {
        assert_eq!(values("1", "3", None), vec!["1", "2", "3"]);
        assert_eq!(values("-2", "1", None), vec!["-2", "-1", "0", "1"]);
        assert_eq!(values("1", "3", Some("2")), vec!["1", "3"]);
        assert!(parameter_scan_values("0", "100000", None).is_err());
        assert!(parameter_scan_values("0", "99999", None).is_ok());
        assert!(parameter_scan_values("0", "200000", Some("2")).is_ok());
        assert!(parameter_scan_values("0", "200001", Some("2")).is_err());
        assert!(parameter_scan_values("0", "2147483647", None).is_err());
    }

    #[test]
    fn decimal_scan() {
        assert_eq!(values("1.50", "3", Some("0.5")), vec!["1.50", "2.00", "2.50", "3.00"]);
        assert_eq!(values("1", "2", Some("0.25")), vec!["1", "1.25", "1.50", "1.75", "2.00"]);
        assert_eq!(values("0", "1", Some("0.3")), vec!["0", "0.3", "0.6", "0.9"]);
        assert_eq!(values("1", "3", Some("1.0")), vec!["1", "2.0", "3.0"]);
        assert_eq!(values("-1.5", "-1", Some("0.25")), vec!["-1.5", "-1.25", "-1.00"]);
        assert!(matches!(parameter_scan_values("1", "3.5", None), Err(ParameterScanError::StepRequired)));
        assert!(matches!(parameter_scan_values("3.5", "1", None), Err(ParameterScanError::StepRequired)));
        assert!(matches!(parameter_scan_values("1", "3.5", Some("0")), Err(ParameterScanError::ZeroStep)));
        assert!(matches!(parameter_scan_values("0", "0", Some("0.000009")), Err(ParameterScanError::TooLarge)));
        assert!(parameter_scan_values("0", "0", Some("0.00001")).is_ok());
        assert!(parameter_scan_values("0", "1.00001", Some("0.00002")).is_ok());
        assert!(parameter_scan_values("0", "1.00002", Some("0.00002")).is_err());
        assert!(parameter_scan_values("0", "0.00001", Some("0.00001")).is_err());
        assert!(parameter_scan_values("1", "2", Some("0.0000000000000000000000000001")).is_err());
    }
}
