//! Benchmark commands and their construction from command-line arguments.

use std::collections::BTreeSet;

use anyhow::{bail, Result};
use clap::ArgMatches;

use crate::parameter::{parameter_scan_values, ParameterValue};

#[derive(Debug, Clone)]
pub struct Command<'a> {
    /// Optional user-provided name (may contain `{param}` placeholders).
    name: Option<&'a str>,
