    parameters: Vec<(&'a str, ParameterValue)>,
}

impl<'a> Command<'a> {
    pub fn new(name: Option<&'a str>, expression: &'a str) -> Command<'a> {
        Command {
            name,
            expression,
            parameters: Vec::new(),
        }
    }

    pub fn new_parametrized(
        name: Option<&'a str>,
        expression: &'a str,
        parameters: Vec<(&'a str, ParameterValue)>,
    ) -> Command<'a> {
        Command {
            name,
            expression,
            parameters,
        }
    }

    fn replace_parameters(&self, template: &str) -> String {
        let mut result = template.to_string();
        for (name, value) in &self.parameters {
            result = result.replace(&format!("{{{}}}", name), &value.to_string());
        }
        result
    }

    /// The display name of the command (user-provided name or command line).
    pub fn get_name(&self) -> String {
        match self.name {
            Some(name) => self.replace_parameters(name),
            None => self.get_command_line(),
        }
    }

    /// The display name, with all parameters that do not occur in the
    /// command line appended.
    pub fn get_name_with_unused_parameters(&self) -> String {
        let unused: Vec<String> = self
            .get_unused_parameters()
            .map(|(name, value)| format!("{} = {}", name, value))
            .collect();
        if unused.is_empty() {
            self.get_name()
        } else {
            format!("{} ({})", self.get_name(), unused.join(", "))
        }
    }

    /// The command line with all parameters substituted.
    pub fn get_command_line(&self) -> String {
        self.replace_parameters(self.expression)
    }

    pub fn get_parameters(&self) -> &[(&'a str, ParameterValue)] {
        &self.parameters
    }

    pub fn get_unused_parameters(&self) -> impl Iterator<Item = &(&'a str, ParameterValue)> {
        let expression = self.expression;
        self.parameters
            .iter()
            .filter(move |(name, _)| !expression.contains(&format!("{{{}}}", name)))
    }
}

pub struct Commands<'a>(Vec<Command<'a>>);

impl<'a> Commands<'a> {
    pub fn from_cli_arguments(matches: &'a ArgMatches) -> Result<Commands<'a>> {
        let command_names: Vec<&str> = matches
            .get_many::<String>("command-name")
            .map(|v| v.map(|s| s.as_str()).collect())
            .unwrap_or_default();
        let command_strings: Vec<&str> = matches
            .get_many::<String>("command")
            .map(|v| v.map(|s| s.as_str()).collect())
            .unwrap_or_default();

        if command_names.len() > command_strings.len() {
            bail!(
                "Too many --command-name options: Expected {} at most",
                command_strings.len()
            );
        }

        let names_and_commands: Vec<(Option<&str>, &str)> = command_strings
            .iter()
            .enumerate()
            .map(|(i, cmd)| (command_names.get(i).copied(), *cmd))
            .collect();

        let mut commands: Vec<Command<'a>> = Vec::new();

        if let Some(reference) = matches.get_one::<String>("reference") {
            let reference_name = matches.get_one::<String>("reference-name").map(|s| s.as_str());
            commands.push(Command::new(reference_name, reference.as_str()));
        }

        if let Some(mut scan_args) = matches.get_many::<String>("parameter-scan") {
            let var = scan_args.next().unwrap().as_str();
            let min = scan_args.next().unwrap().as_str();
            let max = scan_args.next().unwrap().as_str();
            let step = matches
                .get_one::<String>("parameter-step-size")
                .map(|s| s.as_str());
            let values = parameter_scan_values(min, max, step)?;
            for value in values {
                for (name, cmd) in &names_and_commands {
                    commands.push(Command::new_parametrized(
                        *name,
                        cmd,
                        vec![(var, value.clone())],
                    ));
                }
            }
        } else if let Some(occurrences) = matches.get_occurrences::<String>("parameter-list") {
            let lists: Vec<(&str, Vec<&str>)> = occurrences
                .map(|mut occ| {
                    let var = occ.next().unwrap().as_str();
                    let values = occ.next().unwrap().as_str();
                    (var, values.split(',').collect::<Vec<_>>())
                })
                .collect();

            // Check for duplicate parameter names
            let mut seen = BTreeSet::new();
            let mut duplicates = BTreeSet::new();
            for (var, _) in &lists {
                if !seen.insert(*var) {
                    duplicates.insert(*var);
                }
            }
            if !duplicates.is_empty() {
                let dupes: Vec<&str> = duplicates.into_iter().collect();
                bail!("Duplicate parameter names: {}", dupes.join(", "));
            }

            let total: usize = lists.iter().map(|(_, values)| values.len()).product();
            for index in 0..total {
                let mut remainder = index;
                let mut params = Vec::with_capacity(lists.len());
                for (var, values) in &lists {
                    let i = remainder % values.len();
                    remainder /= values.len();
                    params.push((*var, ParameterValue::Text(values[i].to_string())));
                }
                for (name, cmd) in &names_and_commands {
                    commands.push(Command::new_parametrized(*name, cmd, params.clone()));
                }
            }
        } else {
            for (name, cmd) in &names_and_commands {
                commands.push(Command::new(*name, cmd));
            }
        }

        Ok(Commands(commands))
    }

    pub fn iter(&self) -> impl Iterator<Item = &Command<'a>> {
        self.0.iter()
    }

    pub fn len(&self) -> usize {
        self.0.len()
    }
}
