//! Benchmark options and their construction from command-line arguments.

use std::io::IsTerminal;
use std::path::PathBuf;

use anyhow::{bail, Result};
use clap::ArgMatches;

use crate::execute::{InputPolicy, OutputPolicy};
use crate::shell_words;
use crate::units::{Second, Unit};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutputStyleOption {
    /// Do not output with colors or any special formatting
    Basic,
    /// Output with full color and formatting
    Full,
    /// Keep elements such as progress bar, but use no coloring
    NoColor,
    /// Keep coloring, but use no progress bar
    Color,
    /// Disable all the output
    Disabled,
}

impl OutputStyleOption {
    pub fn shows_progress_bar(self) -> bool {
        matches!(self, OutputStyleOption::Full | OutputStyleOption::NoColor)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CmdFailureAction {
    RaiseError,
    IgnoreAll,
    IgnoreCodes(Vec<i32>),
}

impl CmdFailureAction {
    /// Whether the given exit code is considered a failure that should be
    /// reported as an error.
    pub fn is_error(&self, code: Option<i32>) -> bool {
        match self {
            CmdFailureAction::RaiseError => true,
            CmdFailureAction::IgnoreAll => false,
            CmdFailureAction::IgnoreCodes(codes) => match code {
                Some(c) => !codes.contains(&c),
                None => true,
            },
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortOrder {
    Command,
    MeanTime,
}

#[derive(Debug, Clone)]
pub struct Shell {
    pub args: Vec<String>,
}

impl Shell {
    pub fn default_shell() -> Shell {
        Shell {
            args: vec!["sh".to_string()],
        }
    }

    pub fn parse(value: &str) -> Result<Shell> {
        let args = shell_words::split(value).map_err(|e| {
            anyhow::anyhow!("Failed to parse '--shell <command>' expression as command line: {}", e)
        })?;
        if args.is_empty() {
            bail!("An empty command has been specified for the '--shell <command>' option");
        }
        Ok(Shell { args })
    }

    pub fn command(&self) -> std::process::Command {
        let mut cmd = std::process::Command::new(&self.args[0]);
        cmd.args(&self.args[1..]);
        cmd
    }

    pub fn display(&self) -> String {
        shell_words::join(&self.args)
    }
}

#[derive(Debug, Clone)]
pub enum ExecutorKind {
    Raw,
    Shell(Shell),
}

#[derive(Debug, Clone, Copy)]
pub struct RunBounds {
    pub min: u64,
    pub max: Option<u64>,
}

#[derive(Debug, Clone)]
pub struct Options {
    pub warmup_count: u64,
    pub run_bounds: RunBounds,
    pub min_benchmarking_time: Second,
    pub command_failure_action: CmdFailureAction,
    pub setup_command: Option<String>,
    pub preparation_command: Option<Vec<String>>,
    pub conclusion_command: Option<Vec<String>>,
    pub cleanup_command: Option<String>,
    pub output_style: OutputStyleOption,
    pub executor_kind: ExecutorKind,
    pub command_output_policies: Vec<OutputPolicy>,
    pub command_input_policy: InputPolicy,
    pub time_unit: Option<Unit>,
    pub sort_order_speed_comparison: SortOrder,
    pub sort_order_exports: SortOrder,
    pub show_output: bool,
}

fn int_arg(matches: &ArgMatches, name: &str) -> Result<Option<u64>> {
    match matches.get_one::<String>(name) {
        None => Ok(None),
        Some(value) => match value.parse::<u64>() {
            Ok(v) => Ok(Some(v)),
            Err(e) => bail!("Could not read numeric integer argument to '--{}': {}", name, e),
        },
    }
}

impl Options {
    pub fn from_cli_arguments(matches: &ArgMatches) -> Result<Options> {
        let warmup_count = int_arg(matches, "warmup")?.unwrap_or(0);

        let mut run_bounds = RunBounds {
            min: 10,
            max: None,
        };
        let mut min_runs = int_arg(matches, "min-runs")?;
        let mut max_runs = int_arg(matches, "max-runs")?;
        if let Some(runs) = int_arg(matches, "runs")? {
            min_runs = Some(runs);
            max_runs = Some(runs);
        }
        match (min_runs, max_runs) {
            (Some(min), None) => run_bounds.min = min,
            (None, Some(max)) => {
                run_bounds.min = run_bounds.min.min(max);
                run_bounds.max = Some(max);
            }
            (Some(min), Some(max)) if min > max => {
                bail!("Conflicting requirements for the number of runs (empty range, min is larger than max)");
            }
            (Some(min), Some(max)) => {
                run_bounds.min = min;
                run_bounds.max = Some(max);
            }
            (None, None) => {}
        }

        let setup_command = matches.get_one::<String>("setup").cloned();
        let preparation_command = matches
            .get_many::<String>("prepare")
