#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CmdFailureAction {
    RaiseError,
    IgnoreAll,
    IgnoreCodes(Vec<i32>),
}

impl CmdFailureAction {
    /// Whether the given exit code is considered a failure that should be
    /// reported as an error.
    pub fn is_error(&self, code: Option<i32>) -> bool {
        match self {
            CmdFailureAction::RaiseError => true,
            CmdFailureAction::IgnoreAll => false,
            CmdFailureAction::IgnoreCodes(codes) => match code {
                Some(c) => !codes.contains(&c),
                None => true,
            },
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortOrder {
    Command,
    MeanTime,
}

#[derive(Debug, Clone)]
pub struct Shell {
    pub args: Vec<String>,
}

impl Shell {
    pub fn default_shell() -> Shell {
        Shell {
            args: vec!["sh".to_string()],
        }
    }

    pub fn parse(value: &str) -> Result<Shell> {
        let args = shell_words::split(value).map_err(|e| {
            anyhow::anyhow!("Failed to parse '--shell <command>' expression as command line: {}", e)
        })?;
        if args.is_empty() {
            bail!("An empty command has been specified for the '--shell <command>' option");
        }
        Ok(Shell { args })
    }

    pub fn command(&self) -> std::process::Command {
        let mut cmd = std::process::Command::new(&self.args[0]);
        cmd.args(&self.args[1..]);
        cmd
    }

    pub fn display(&self) -> String {
        shell_words::join(&self.args)
    }
}

