//! Computation of relative speeds between benchmark results.

use std::cmp::Ordering;

use crate::benchmark::BenchmarkResult;
use crate::options::SortOrder;
use crate::units::Scalar;

pub struct BenchmarkResultWithRelativeSpeed<'a> {
    pub result: &'a BenchmarkResult,
    pub relative_speed: Scalar,
    pub relative_speed_stddev: Option<Scalar>,
    pub is_reference: bool,
}

pub fn compare_mean_time(l: &BenchmarkResult, r: &BenchmarkResult) -> Ordering {
    l.mean.partial_cmp(&r.mean).unwrap_or(Ordering::Equal)
}

pub fn fastest_of<'a>(results: &'a [BenchmarkResult]) -> &'a BenchmarkResult {
    results
        .iter()
        .min_by(|l, r| compare_mean_time(l, r))
        .expect("at least one benchmark result")
}

fn compute_relative_speeds<'a>(
    results: &'a [BenchmarkResult],
    reference: &'a BenchmarkResult,
    sort_order: SortOrder,
) -> Vec<BenchmarkResultWithRelativeSpeed<'a>> {
    let reference_mean = reference.mean;
    let mut annotated: Vec<BenchmarkResultWithRelativeSpeed<'a>> = results
        .iter()
        .map(|result| {
            let is_reference = std::ptr::eq(result, reference);
            let ratio = result.mean / reference_mean;
            // Propagation of uncertainty (independent variables, no covariance)
            let ratio_stddev = match (result.stddev, reference.stddev) {
                (Some(result_stddev), Some(reference_stddev)) => Some(
                    ratio
                        * ((result_stddev / result.mean).powi(2)
                            + (reference_stddev / reference_mean).powi(2))
                        .sqrt(),
                ),
                _ => None,
            };
            BenchmarkResultWithRelativeSpeed {
                result,
                relative_speed: ratio,
                relative_speed_stddev: ratio_stddev,
                is_reference,
            }
        })
        .collect();

    match sort_order {
        SortOrder::Command => {}
        SortOrder::MeanTime => {
            annotated.sort_by(|l, r| compare_mean_time(l.result, r.result));
        }
    }
    annotated
}

/// Compute relative speeds, or `None` if the reference has a mean time of
/// zero (in which case no meaningful comparison is possible).
pub fn compute_with_check<'a>(
    results: &'a [BenchmarkResult],
    reference: &'a BenchmarkResult,
    sort_order: SortOrder,
) -> Option<Vec<BenchmarkResultWithRelativeSpeed<'a>>> {
    if reference.mean == 0.0 {
        return None;
    }
    Some(compute_relative_speeds(results, reference, sort_order))
}

/// Compute relative speeds without checking for a zero reference time.
pub fn compute<'a>(
    results: &'a [BenchmarkResult],
    reference: &'a BenchmarkResult,
    sort_order: SortOrder,
) -> Vec<BenchmarkResultWithRelativeSpeed<'a>> {
    compute_relative_speeds(results, reference, sort_order)
}
