            ExecutorKind::Raw => {
                let mut args = crate::shell_words::split(&command_line).map_err(|e| {
                    anyhow!("Failed to parse command '{}': {}", command_line, e)
                })?;
                if args.is_empty() {
                    bail!("Can not execute empty command");
                }
                let program = args.remove(0);
                let mut cmd = std::process::Command::new(&program);
                cmd.args(&args);
                run_command_and_measure_common(
                    cmd,
                    iteration,
                    failure_action,
                    &self.options.command_input_policy,
                    output_policy,
                    &command_line,
                )?
            }
            ExecutorKind::Shell(shell) => {
                let mut cmd = shell.command();
                cmd.arg("-c").arg(&command_line);
                run_command_and_measure_common(
                    cmd,
                    iteration,
                    failure_action,
                    &self.options.command_input_policy,
                    output_policy,
                    &command_line,
                )?
            }
        };

        let mut timing = TimingResult {
            time_real: result.time_real,
            time_user: result.time_user,
            time_system: result.time_system,
            memory_usage_byte: result.memory_usage_byte,
        };

        if let Some(spawning) = &self.shell_spawning_time {
            timing.time_real = (timing.time_real - spawning.time_real).max(0.0);
            timing.time_user = (timing.time_user - spawning.time_user).max(0.0);
            timing.time_system = (timing.time_system - spawning.time_system).max(0.0);
        }

        Ok((timing, result.status))
    }

    /// Measure the time it takes for the shell to spawn an empty command.
    pub fn calibrate(&mut self) -> Result<()> {
        let shell = match &self.kind {
            ExecutorKind::Raw => return Ok(()),
            ExecutorKind::Shell(shell) => shell.clone(),
        };

        let mut progress_bar = if self.options.output_style.shows_progress_bar() {
            ProgressBar::new(SHELL_CALIBRATION_RUNS, "Measuring shell spawning time")
        } else {
            ProgressBar::hidden()
        };

        let mut times_real = Vec::with_capacity(SHELL_CALIBRATION_RUNS as usize);
        let mut times_user = Vec::with_capacity(SHELL_CALIBRATION_RUNS as usize);
        let mut times_system = Vec::with_capacity(SHELL_CALIBRATION_RUNS as usize);

        let output_policy = OutputPolicy::Null;
        let input_policy = InputPolicy::Null;

        for _ in 0..SHELL_CALIBRATION_RUNS {
            let mut cmd = shell.command();
            cmd.arg("-c").arg("");
            let result = execute_and_measure(cmd, &input_policy, &output_policy);
            let ok = match result {
                Ok(res) if res.status.success() => {
                    times_real.push(res.time_real);
                    times_user.push(res.time_user);
                    times_system.push(res.time_system);
                    true
                }
                _ => false,
            };
            if !ok {
                progress_bar.finish_and_clear();
                bail!(
                    "Could not measure shell execution time. Make sure you can run '{} -c \"\"'.",
                    shell_display(&shell)
                );
            }
            progress_bar.inc(1);
        }
        progress_bar.finish_and_clear();

        self.shell_spawning_time = Some(TimingResult {
            time_real: mean(&times_real),
            time_user: mean(&times_user),
            time_system: mean(&times_system),
            memory_usage_byte: 0,
        });
        Ok(())
    }

    pub fn is_shell(&self) -> bool {
        matches!(self.kind, ExecutorKind::Shell(_))
    }
}

fn shell_display(shell: &Shell) -> String {
    shell.display()
}

pub struct Benchmark<'a> {
    number: usize,
    command: &'a Command<'a>,
    options: &'a Options,
    executor: &'a Executor<'a>,
}

impl<'a> Benchmark<'a> {
    pub fn new(
        number: usize,
        command: &'a Command<'a>,
        options: &'a Options,
        executor: &'a Executor<'a>,
    ) -> Benchmark<'a> {
        Benchmark {
            number,
            command,
            options,
            executor,
        }
    }

    fn output_policy(&self) -> &OutputPolicy {
        let policies = &self.options.command_output_policies;
        if policies.len() == 1 {
            &policies[0]
        } else {
            &policies[self.number]
        }
    }

    fn per_command(&self, commands: &Option<Vec<String>>) -> Option<String> {
        commands.as_ref().map(|cmds| {
            if cmds.len() == 1 {
                cmds[0].clone()
            } else {
                cmds[self.number].clone()
            }
        })
    }

    /// Run an auxiliary command (setup, prepare, conclude, cleanup).
    fn run_auxiliary_command(
        &self,
        command: &Option<String>,
        error_message: &str,
    ) -> Result<Option<TimingResult>> {
        let Some(command) = command else {
            return Ok(None);
        };
        let command = Command::new_parametrized(
            None,
            command,
            self.command.get_parameters().to_vec(),
        );
        let output_policy = if self.options.show_output {
            OutputPolicy::Inherit
        } else {
            OutputPolicy::Null
        };
        let (res, status) = self.executor.run_command_and_measure(
            &command,
            BenchmarkIteration::NonBenchmarkRun,
            Some(&CmdFailureAction::IgnoreAll),
            &output_policy,
        )?;
        if !status.success() {
            bail!("{}", error_message);
        }
        Ok(Some(res))
    }

    fn run_setup_command(&self) -> Result<()> {
        self.run_auxiliary_command(
            &self.options.setup_command,
            "The setup command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.",
        )?;
        Ok(())
    }

    fn run_preparation_command(&self) -> Result<()> {
        let cmd = self.per_command(&self.options.preparation_command);
        self.run_auxiliary_command(
            &cmd,
            "The preparation command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.",
        )?;
        Ok(())
    }

    fn run_conclusion_command(&self) -> Result<()> {
        let cmd = self.per_command(&self.options.conclusion_command);
        self.run_auxiliary_command(
            &cmd,
            "The conclusion command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.",
        )?;
        Ok(())
    }

    fn run_cleanup_command(&self) -> Result<()> {
        self.run_auxiliary_command(
            &self.options.cleanup_command,
            "The cleanup command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.",
        )?;
        Ok(())
    }

    pub fn run(&self) -> Result<BenchmarkResult> {
        let style = self.options.output_style;
        let output_policy = self.output_policy();

        if style != OutputStyleOption::Disabled {
            println!(
                "{}{}: {}",
                "Benchmark ".bold(),
                (self.number + 1).to_string().bold(),
                self.command.get_name_with_unused_parameters()
            );
        }

        self.run_setup_command()?;

        // Warmup runs
        if self.options.warmup_count > 0 {
            let mut bar = if style.shows_progress_bar() {
                ProgressBar::new(self.options.warmup_count, "Performing warmup runs")
            } else {
                ProgressBar::hidden()
            };
            for i in 0..self.options.warmup_count {
                self.run_preparation_command()?;
                let _ = self.executor.run_command_and_measure(
                    self.command,
                    BenchmarkIteration::Warmup(i),
                    None,
                    output_policy,
                )?;
                self.run_conclusion_command()?;
                bar.inc(1);
            }
            bar.finish_and_clear();
        }

        let mut bar = if style.shows_progress_bar() {
            ProgressBar::new(self.options.run_bounds.min, "Initial time measurement")
        } else {
            ProgressBar::hidden()
        };

        let mut times_real: Vec<Second> = Vec::new();
        let mut times_user: Vec<Second> = Vec::new();
        let mut times_system: Vec<Second> = Vec::new();
        let mut memory_usage: Vec<u64> = Vec::new();
        let mut exit_codes: Vec<Option<i32>> = Vec::new();
        let mut all_succeeded = true;

        // Initial run
        self.run_preparation_command()?;
        let (res, status) = self.executor.run_command_and_measure(
            self.command,
            BenchmarkIteration::Benchmark(0),
            None,
            output_policy,
        )?;
        self.run_conclusion_command()?;

        let runs_in_min_time = (self.options.min_benchmarking_time / res.time_real) as u64;
        let count = {
            let min = std::cmp::max(runs_in_min_time, self.options.run_bounds.min);
            match self.options.run_bounds.max {
                Some(max) => std::cmp::min(min, max),
                None => min,
            }
        };
        let count_remaining = count.wrapping_sub(1);

        times_real.push(res.time_real);
        times_user.push(res.time_user);
        times_system.push(res.time_system);
        memory_usage.push(res.memory_usage_byte);
        exit_codes.push(exit_code(&status));
        all_succeeded = all_succeeded && status.success();

        bar.set_length(count);
        bar.inc(1);

        let mut i: u64 = 1;
        let mut remaining = count_remaining;
        while remaining > 0 {
            self.run_preparation_command()?;
            let msg = {
                let mean_str = format_duration(mean(&times_real), self.options.time_unit);
                format!("Current estimate: {}", mean_str.green())
            };
            bar.set_message(msg);

            let (res, status) = self.executor.run_command_and_measure(
                self.command,
                BenchmarkIteration::Benchmark(i),
                None,
                output_policy,
            )?;
            times_real.push(res.time_real);
            times_user.push(res.time_user);
            times_system.push(res.time_system);
            memory_usage.push(res.memory_usage_byte);
            exit_codes.push(exit_code(&status));
            all_succeeded = all_succeeded && status.success();

            self.run_conclusion_command()?;
            bar.inc(1);
            i += 1;
            remaining -= 1;
        }
        bar.finish_and_clear();

        // Statistics
        let t_mean = mean(&times_real);
        let t_stddev = if times_real.len() > 1 {
            Some(standard_deviation(&times_real, Some(t_mean)))
        } else {
            None
        };
        let t_median = median(&times_real);
        let t_min = min(&times_real);
        let t_max = max(&times_real);
        let user_mean = mean(&times_user);
        let system_mean = mean(&times_system);

        let (mean_str, time_unit) = format_duration_unit(t_mean, self.options.time_unit);
        let min_str = format_duration(t_min, Some(time_unit));
        let max_str = format_duration(t_max, Some(time_unit));
        let num_str = format!("{} runs", times_real.len());
        let user_str = format_duration(user_mean, Some(time_unit));
        let system_str = format_duration(system_mean, Some(time_unit));

        if style != OutputStyleOption::Disabled {
            if times_real.len() == 1 {
                println!(
                    "  Time ({} ≡):        {:>8}               [User: {}, System: {}]",
                    "abs".green().bold(),
                    mean_str.green().bold(),
                    user_str.blue(),
                    system_str.blue()
                );
            } else {
                let stddev_str = format_duration(t_stddev.unwrap(), Some(time_unit));
                println!(
                    "  Time ({} ± {}):     {:>8} ± {:>8}    [User: {}, System: {}]",
                    "mean".green().bold(),
                    "σ".green(),
                    mean_str.green().bold(),
                    stddev_str.green(),
                    user_str.blue(),
                    system_str.blue()
                );
                println!(
                    "  Range ({} … {}):   {:>8} … {:>8}    {}",
                    "min".cyan(),
                    "max".purple(),
                    min_str.cyan(),
                    max_str.purple(),
                    num_str.dimmed()
                );
            }
        }

        // Warnings
        let mut warnings: Vec<String> = Vec::new();

        if self.executor.is_shell() && times_real.iter().any(|&t| t < MIN_EXECUTION_TIME) {
            warnings.push(
                "Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.".to_string(),
            );
        }

        if !all_succeeded {
            warnings.push("Ignoring non-zero exit code.".to_string());
        }

        let scores = modified_zscores(&times_real);
        if scores[0] > OUTLIER_THRESHOLD {
            warnings.push(format!(
                "The first benchmarking run for this command was significantly slower than the rest ({}). This could be caused by (filesystem) caches that were not filled until after the first run. You should consider using the '--warmup' option to fill those caches before the actual benchmark. Alternatively, use the '--prepare' option to clear the caches before each timing run.",
                format_duration(times_real[0], Some(time_unit))
            ));
        } else if scores.iter().any(|&s| s.abs() > OUTLIER_THRESHOLD) {
            warnings.push(
                "Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.".to_string(),
            );
        }

        if !warnings.is_empty() {
            eprintln!(" ");
            for warning in &warnings {
                eprintln!("  {}: {}", "Warning".yellow(), warning);
            }
        }

        if style != OutputStyleOption::Disabled {
            println!(" ");
        }

        self.run_cleanup_command()?;

        let parameters = self
            .command
            .get_parameters()
            .iter()
            .map(|(name, value)| (name.to_string(), value.to_string()))
            .collect();

        Ok(BenchmarkResult {
            command: self.command.get_name(),
            command_with_unused_parameters: self.command.get_name_with_unused_parameters(),
            mean: t_mean,
            stddev: t_stddev,
            median: t_median,
            user: user_mean,
            system: system_mean,
            min: t_min,
            max: t_max,
            times: times_real,
            memory_usage_byte: memory_usage,
            exit_codes,
            parameters,
        })
    }
}

/// Memory usage helper used by exports (bytes).
pub fn unit_or_auto(unit: Option<Unit>, duration: Second) -> Unit {
    unit.unwrap_or_else(|| crate::units::auto_unit(duration))
}
