//! Export of benchmark results to various file formats.

use std::fs::File;
use std::io::Write;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use serde::Serialize;

use crate::benchmark::BenchmarkResult;
use crate::options::SortOrder;
use crate::relative_speed::{self, BenchmarkResultWithRelativeSpeed};
use crate::units::{Second, Unit};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExportType {
    Asciidoc,
    Csv,
    Json,
    Markdown,
    Orgmode,
}

struct ExportTarget {
    export_type: ExportType,
    path: PathBuf,
}

pub struct ExportManager {
    targets: Vec<ExportTarget>,
    time_unit: Option<Unit>,
    sort_order: SortOrder,
}

impl ExportManager {
    pub fn from_cli_arguments(
        matches: &clap::ArgMatches,
        time_unit: Option<Unit>,
        sort_order: SortOrder,
    ) -> Result<ExportManager> {
        let mut manager = ExportManager {
            targets: Vec::new(),
            time_unit,
            sort_order,
        };
        let types = [
            ("export-asciidoc", ExportType::Asciidoc),
            ("export-csv", ExportType::Csv),
            ("export-json", ExportType::Json),
            ("export-markdown", ExportType::Markdown),
            ("export-orgmode", ExportType::Orgmode),
        ];
        for (arg, export_type) in types {
            if let Some(path) = matches.get_one::<String>(arg) {
                manager.add_target(export_type, path)?;
            }
        }
        Ok(manager)
    }

    fn add_target(&mut self, export_type: ExportType, path: &str) -> Result<()> {
        // Create (and truncate) the file right away to catch errors early.
        File::create(path)
            .with_context(|| format!("Could not create export file '{}'", path))?;
        self.targets.push(ExportTarget {
            export_type,
            path: PathBuf::from(path),
        });
        Ok(())
    }

    /// Write the results to all export targets.
    pub fn write_results(
        &self,
        results: &[BenchmarkResult],
        reference: Option<&BenchmarkResult>,
    ) -> Result<()> {
        for target in &self.targets {
            let content = match target.export_type {
                ExportType::Asciidoc => {
                    markup::export(results, reference, self.time_unit, self.sort_order, &markup::Asciidoc)
                }
                ExportType::Csv => csv::export(results),
                ExportType::Json => json::export(results),
                ExportType::Markdown => {
                    markup::export(results, reference, self.time_unit, self.sort_order, &markup::Markdown)
                }
                ExportType::Orgmode => {
                    markup::export(results, reference, self.time_unit, self.sort_order, &markup::Orgmode)
                }
            };
            write_file(&target.path, &content)?;
        }
        Ok(())
    }
}

fn write_file(path: &Path, content: &[u8]) -> Result<()> {
    let mut file = File::create(path)
        .with_context(|| format!("Could not create export file '{}'", path.display()))?;
    file.write_all(content)
        .with_context(|| format!("Could not write to export file '{}'", path.display()))?;
    Ok(())
}

mod json {
    use super::*;
    use std::collections::BTreeMap;

    #[derive(Serialize)]
    struct Entry<'a> {
        command: &'a str,
        mean: Second,
        stddev: Option<Second>,
        median: Second,
        user: Second,
        system: Second,
        min: Second,
        max: Second,
        times: &'a [Second],
        memory_usage_byte: &'a [u64],
        exit_codes: &'a [Option<i32>],
        #[serde(skip_serializing_if = "BTreeMap::is_empty")]
        parameters: &'a BTreeMap<String, String>,
    }

    #[derive(Serialize)]
    struct Document<'a> {
        results: Vec<Entry<'a>>,
    }

    pub fn export(results: &[BenchmarkResult]) -> Vec<u8> {
        let doc = Document {
            results: results
                .iter()
                .map(|r| Entry {
                    command: &r.command,
                    mean: r.mean,
                    stddev: r.stddev,
                    median: r.median,
                    user: r.user,
                    system: r.system,
                    min: r.min,
                    max: r.max,
                    times: &r.times,
                    memory_usage_byte: &r.memory_usage_byte,
                    exit_codes: &r.exit_codes,
                    parameters: &r.parameters,
                })
                .collect(),
        };
        let mut out = serde_json::to_vec_pretty(&doc).expect("serialization can not fail");
        out.push(b'\n');
