cat > src/main.rs <<'EOF'
mod benchmark;
mod cli;
mod command;
mod decimal;
mod execute;
mod export;
mod options;
mod outliers;
mod parameter;
mod progress_bar;
mod relative_speed;
mod shell_words;
mod statistics;
mod units;

use anyhow::Result;
use colored::Colorize;

use benchmark::{Benchmark, BenchmarkResult, Executor};
use command::Commands;
use export::ExportManager;
use options::{Options, OutputStyleOption, SortOrder};

fn print_summary(results: &[BenchmarkResult], reference_given: bool, options: &Options) {
    if results.len() < 2 {
        return;
    }
    let reference = if reference_given {
        &results[0]
    } else {
        relative_speed::fastest_of(results)
    };

    let sort_order = options.sort_order_speed_comparison;
    match relative_speed::compute_with_check(results, reference, sort_order) {
        Some(annotated) => match sort_order {
            SortOrder::MeanTime => {
                println!("{}", "Summary".bold());
                println!(
                    "  {} ran",
                    reference.command_with_unused_parameters.cyan()
                );
                for entry in annotated.iter().filter(|e| !e.is_reference) {
                    let (ratio, comparison) = if entry.relative_speed < 1.0 {
                        (1.0 / entry.relative_speed, "slower")
                    } else {
                        (entry.relative_speed, "faster")
                    };
                    let stddev = entry.relative_speed_stddev.map(|s| {
                        if entry.relative_speed < 1.0 {
                            // Scale the uncertainty along with the inverted ratio
                            s / entry.relative_speed / entry.relative_speed
                        } else {
                            s
                        }
                    });
                    let stddev_str = match stddev {
                        Some(s) => format!(" ± {}", format!("{:.2}", s).green()),
                        None => String::new(),
                    };
                    println!(
                        "{}{} times {} than {}",
                        format!("{:8.2}", ratio).green().bold(),
                        stddev_str,
                        comparison,
                        entry.result.command_with_unused_parameters.magenta()
                    );
                }
            }
            SortOrder::Command => {
                println!("{}", "Relative speed comparison".bold());
                for entry in &annotated {
                    let stddev_str = match entry.relative_speed_stddev {
                        Some(s) => format!(" ± {}", format!("{:5.2}", s).green()),
                        None => " ".repeat(10),
                    };
                    println!(
                        "  {}{}  {}",
                        format!("{:10.2}", entry.relative_speed).green().bold(),
                        stddev_str,
                        entry.result.command_with_unused_parameters
                    );
                }
            }
        },
        None => {
            eprintln!(
                "{}: The benchmark comparison could not be computed as some benchmark times are zero. \
                 This could be caused by background interference during the initial calibration phase \
                 of hyperfine, in combination with very fast commands (faster than a few milliseconds). \
                 Try to re-run the benchmark on a quiet system. If you did not do so already, try the \
                 --shell=none/-N option. If it does not help either, you command is most likely too fast \
                 to be accurately benchmarked by hyperfine.",
                "Note".red().bold()
            );
        }
    }
}

fn run() -> Result<()> {
    let matches = cli::get_arg_matches(std::env::args_os());
    let options = Options::from_cli_arguments(&matches)?;
    let commands = Commands::from_cli_arguments(&matches)?;
    let export_manager =
        ExportManager::from_cli_arguments(&matches, options.time_unit, options.sort_order_exports)?;

    options.validate_per_command_options(commands.len())?;

    let reference_given = matches.contains_id("reference");

    let mut executor = Executor::new(&options);
    executor.calibrate()?;

    let mut results: Vec<BenchmarkResult> = Vec::new();
    for (number, command) in commands.iter().enumerate() {
        let result = Benchmark::new(number, command, &options, &executor).run()?;
        results.push(result);

        // Export intermediate results
        let reference = if reference_given { results.first() } else { None };
        export_manager.write_results(&results, reference)?;
    }

    if options.output_style != OutputStyleOption::Disabled {
        print_summary(&results, reference_given, &options);
    }

    let reference = if reference_given { results.first() } else { None };
    export_manager.write_results(&results, reference)?;

    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("{} {:#}", "Error:".red(), e);
        std::process::exit(1);
    }
}
